package com.yeyamo_mobile.api.interaction_service.infrastructure.persistence;import jakarta.persistence.*;import java.time.*;import java.util.*;
@Entity@Table(name="generic_interactions")public class GenericInteractionEntity{public enum TargetType{POST,PLACE,EVENT,EXPERIENCE,ARTWORK,CULTURE_CONTENT,CHALLENGE_SUBMISSION,DAILY_WORD,CULTURE_CHALLENGE,ARTISAN}public enum Type{LIKE,FAVORITE,COMMENT,SHARE,REPORT,VIEW,FOLLOW}public enum Status{ACTIVE,REMOVED,PENDING_MODERATION}@Id public UUID id;@Enumerated(EnumType.STRING)@Column(name="target_type")public TargetType targetType;@Column(name="target_id")public String targetId;@Column(name="user_id")public String userId;@Enumerated(EnumType.STRING)@Column(name="interaction_type")public Type interactionType;public String body;public String channel;@Enumerated(EnumType.STRING)public Status status;@Column(name="created_at")public Instant createdAt;@Column(name="updated_at")public Instant updatedAt;@Version public long version;@PrePersist void c(){createdAt=updatedAt=Instant.now();}@PreUpdate void u(){updatedAt=Instant.now();}}
